s=s.replace('Orbit Outcomes: Energy and Gravity','Change Velocity &amp; Transfer Orbits').replace('Orbit, escape, or crash?','Change speed. Change orbit.').replace('The same spacecraft starts at the same distance from Earth. Change its sideways speed, calculate its energy, and predict its path.','Add or subtract sideways velocity, test the flight path, then use two burns to reach a higher circular orbit.')
a=s.index('<nav class="tabs"');b=s.index('</nav>',a)+6
s=s[:a]+'''<nav class="tabs" aria-label="Choose an activity"><button id="experiment-tab" aria-pressed="true">1 · Change velocity &amp; test</button><button id="transfer-tab" aria-pressed="false">2 · Hohmann transfer</button></nav>'''+s[b:]
s=s.replace('<circle cx="250" cy="220" r="128" fill="none" stroke="#446274" stroke-dasharray="4 6"/>','<circle cx="250" cy="220" r="90" fill="none" stroke="#678695" stroke-dasharray="4 6"/><circle id="target-orbit" cx="250" cy="220" r="180" fill="none" stroke="#d6aa55" stroke-dasharray="6 6" visibility="hidden"/><path id="planned" fill="none" stroke="#e0b360" stroke-width="2" stroke-dasharray="5 5"/><g id="burn-markers" visibility="hidden" fill="#ffe2a0" font-size="13"><text x="345" y="245">Burn 1</text><text x="35" y="245">Burn 2</text></g>')
s=s.replace('r="60" fill="#44a4cf"','r="43" fill="#44a4cf"').replace('r="58.25"','r="40.96"').replace('<path d="M218 183','<path transform="translate(75 66) scale(.7)" d="M218 183').replace('y="300" text-anchor','y="280" text-anchor')
a=s.index('<section class="work"');b=s.index('</main><script>',a)
s=s[:a]+'''<section class="work" aria-labelledby="problem-title"><h2 id="problem-title">Set a velocity change</h2>
<div class="given">Start in a circular orbit: <strong>5.34 km/s</strong> at <strong>14,000 km</strong> from Earth's center. Each test starts here.</div>
<div id="experiment-controls"><p class="control-label"><label for="delta">Sideways velocity change</label><output id="delta-value" for="delta">+0.00 km/s</output></p><input id="delta" type="range" min="-3" max="3" step=".1" value="0"><div class="controls adjustment"><button id="subtract">− Subtract 0.1</button><button id="add">+ Add 0.1</button><button id="zero">Zero change</button></div><p class="small">Left slows the spacecraft against its motion. Right speeds it up along its motion. The change is a single brief engine burn.</p><div class="metrics"><div class="metric"><span>Speed after burn</span><strong id="speed"></strong></div><div class="metric"><span>Energy after burn</span><strong id="energy"></strong></div></div><button id="test" class="primary">Test this velocity</button><div id="result" class="feedback" role="status">Choose a change, then test it.</div><button id="next" class="primary">Explore a Hohmann transfer →</button></div>
<div id="transfer-controls" hidden><p class="transfer-intro">Move from a 14,000 km radius to a <strong>28,000 km radius</strong>. Two forward burns connect the circular orbits with half an ellipse.</p><ol class="steps"><li id="step1"><strong>Burn 1 · Enter the transfer ellipse</strong><br>Add <span id="dv1"></span> along the current motion.</li><li id="step2"><strong>Coast · Engines off</strong><br>Gravity slows the spacecraft as it climbs to the farthest point.</li><li id="step3"><strong>Burn 2 · Make the new orbit circular</strong><br>Add <span id="dv2"></span> at the farthest point.</li></ol><button id="burn1" class="primary">Fire burn 1</button><button id="coast" hidden>Skip to burn 2 location</button><button id="burn2" class="primary" hidden>Fire burn 2</button><button id="restart" hidden>Restart transfer</button><div id="transfer-status" class="feedback" role="status">Ready at the inner orbit. Fire the first burn to begin.</div><div class="metrics"><div class="metric"><span>Current speed</span><strong id="live-speed"></strong></div><div class="metric"><span>Distance from center</span><strong id="live-radius"></strong></div></div><p class="small">Both burns add speed. The final circular speed is lower than the initial speed because the spacecraft climbs between burns.</p></div>
</section></div><footer class="takeaway"><p><strong>Gravity stays active:</strong> it bends the trajectory throughout the flight. A small slowdown can make a safe ellipse; a larger slowdown can send the path into Earth.</p><p class="progress" id="progress" role="status">Try an increase, try a decrease, then complete both transfer burns.</p></footer>
</main><script>
const $=id=>document.getElementById(id),mu=398600,r0=14000,vc=Math.sqrt(mu/r0),R=6371/r0;
const kTransfer=Math.sqrt(4/3),dv1=vc*(kTransfer-1),dv2=vc*(Math.sqrt(.5)-kTransfer/2);
let mode='experiment',phase='ready',points=[],cursor=0,paused=true,last=0,outcome='',tested=new Set(),transferDone=false,sent=false;
function trajectory(k){let x=1,y=0,vx=0,vy=k,angle=0,previous=0;const list=[],dt=.004;for(let i=0;i<16000;i++){const r=Math.hypot(x,y);list.push({x,y,vx,vy});if(r<=R||r>2.35||angle>=2*Math.PI)break;const ax=-x/r**3,ay=-y/r**3;x+=vx*dt+ax*dt*dt/2;y+=vy*dt+ay*dt*dt/2;const n=Math.hypot(x,y);vx+=(ax-x/n**3)*dt/2;vy+=(ay-y/n**3)*dt/2;const theta=Math.atan2(y,x);let d=theta-previous;if(d<-Math.PI)d+=2*Math.PI;angle+=d;previous=theta;}return list;}
function transferPath(){const list=[],a=1.5,e=1/3,n=1/Math.sqrt(a**3);for(let i=0;i<=800;i++){const M=Math.PI*i/800;let E=M;for(let j=0;j<8;j++)E-=(E-e*Math.sin(E)-M)/(1-e*Math.cos(E));const rate=n/(1-e*Math.cos(E));list.push({x:a*(Math.cos(E)-e),y:a*Math.sqrt(1-e*e)*Math.sin(E),vx:-a*Math.sin(E)*rate,vy:a*Math.sqrt(1-e*e)*Math.cos(E)*rate});}return list;}
function outerPath(){return Array.from({length:1201},(_,i)=>{const a=Math.PI+2*Math.PI*i/1200;return {x:2*Math.cos(a),y:2*Math.sin(a),vx:-Math.sin(a)/Math.sqrt(2),vy:Math.cos(a)/Math.sqrt(2)};});}
const xy=p=>[250+p.x*90,220-p.y*90],path=list=>list.filter((_,i)=>i%3===0||i===list.length-1).map((p,i)=>(i?'L':'M')+xy(p).join(' ')).join(' ');
function draw(){const p=points[Math.min(Math.floor(cursor),points.length-1)],[x,y]=xy(p),r=Math.hypot(p.x,p.y),v=Math.hypot(p.vx,p.vy);$('craft').setAttribute('transform',`translate(${x} ${y})`);$('trail').setAttribute('d',path(points.slice(0,Math.floor(cursor)+1)));$('g-arrow').setAttribute('d',`M${x} ${y}l${-p.x/r*30} ${p.y/r*30}`);$('v-arrow').setAttribute('d',`M${x} ${y}l${p.vx/v*32} ${-p.vy/v*32}`);$('live-speed').textContent=(vc*v).toFixed(2)+' km/s';$('live-radius').textContent=Math.round(r*r0).toLocaleString('en-US')+' km';}
function label(){$('play').textContent=paused?'Play motion':'Pause motion';}
function progress(){if(tested.has('add')&&tested.has('subtract')&&transferDone){$('progress').textContent='Velocity tests and Hohmann transfer completed.';if(!sent){window.parent.postMessage({ type: 'complete' }, '*');sent=true;}}else $('progress').textContent=`Increase tested: ${tested.has('add')?'yes':'not yet'} · Decrease tested: ${tested.has('subtract')?'yes':'not yet'} · Transfer: ${transferDone?'complete':'not yet'}`;}
function preview(){const dv=Number($('delta').value),v=vc+dv;$('delta-value').textContent=(dv>=0?'+':'')+dv.toFixed(2)+' km/s';$('speed').textContent=v.toFixed(2)+' km/s';$('energy').textContent=(v*v/2-mu/r0).toFixed(2)+' MJ/kg';points=[{x:1,y:0,vx:0,vy:v/vc}];cursor=0;paused=true;label();$('scene-state').textContent='Ready to test';$('result').textContent='New setting ready. Press Test this velocity to apply it.';$('scene-caption').textContent='The spacecraft starts on the right side of the circular orbit. Its velocity points upward.';draw();}
function test(){const dv=Number($('delta').value),k=(vc+dv)/vc,energy=k*k/2-1,peri=k<1?k*k/(2-k*k):1;points=trajectory(k);cursor=0;paused=false;label();if(dv>0)tested.add('add');if(dv<0)tested.add('subtract');outcome=peri<=R?'Collision course':energy>=0?'Escape trajectory':Math.abs(dv)<.00001?'Circular orbit':'Elliptical orbit';$('scene-state').textContent=outcome;const detail=peri<=R?'This slowdown puts the closest approach inside Earth. The path ends at the surface.':energy>=0?'The energy is zero or positive: the spacecraft can escape. It still slows under gravity as it moves away.':dv===0?'No burn: gravity maintains the original circular path.':dv>0?'Adding speed raises the opposite side of the orbit. One burn produces an ellipse, not a higher circle.':'Subtracting speed lowers the opposite side of the orbit. This ellipse still clears Earth.';$('result').textContent=detail;$('scene-caption').textContent=detail;$('scene-desc').textContent=outcome+'. '+detail;progress();draw();}
function setMode(next){mode=next;$('experiment-controls').hidden=next!=='experiment';$('transfer-controls').hidden=next!=='transfer';$('experiment-tab').setAttribute('aria-pressed',String(next==='experiment'));$('transfer-tab').setAttribute('aria-pressed',String(next==='transfer'));$('target-orbit').setAttribute('visibility',next==='transfer'?'visible':'hidden');$('burn-markers').setAttribute('visibility',next==='transfer'?'visible':'hidden');$('planned').setAttribute('d','');$('problem-title').textContent=next==='transfer'?'Hohmann transfer: two burns':'Set a velocity change';if(next==='experiment')preview();else resetTransfer();}
function resetTransfer(){phase='ready';points=[{x:1,y:0,vx:0,vy:1}];cursor=0;paused=true;label();$('planned').setAttribute('d',path(transferPath()));$('burn1').hidden=false;$('burn2').hidden=true;$('coast').hidden=true;$('restart').hidden=true;$('scene-state').textContent='Ready for burn 1';$('transfer-status').textContent='Ready at 14,000 km. Burn 1 adds '+dv1.toFixed(2)+' km/s.';$('scene-caption').textContent='Dashed gold: the target circle and connecting transfer ellipse.';$('scene-desc').textContent='An inner circular orbit, a larger target circle, and an ellipse tangent to both.';document.querySelectorAll('.steps li').forEach(e=>e.className='');$('step1').className='active';draw();}
function arrive(){cursor=points.length-1;phase='arrival';paused=true;label();$('coast').hidden=true;$('burn2').hidden=false;$('step2').className='';$('step3').className='active';$('scene-state').textContent='Ready for burn 2';$('transfer-status').textContent='At 28,000 km: speed is '+(vc*kTransfer/2).toFixed(2)+' km/s. Add '+dv2.toFixed(2)+' km/s to match the new circular speed. Without this burn, the spacecraft would fall back along the ellipse.';draw();}
$('burn1').onclick=()=>{phase='coasting';points=transferPath();cursor=0;paused=false;label();$('burn1').hidden=true;$('coast').hidden=false;$('step1').className='';$('step2').className='active';$('scene-state').textContent='Coasting outward';$('transfer-status').textContent='Burn 1 complete. Speed increased to '+(vc*kTransfer).toFixed(2)+' km/s. Engines off: coast for half an ellipse (about '+(Math.PI*Math.sqrt(21000**3/mu)/3600).toFixed(2)+' hours of real flight).';draw();};
$('coast').onclick=arrive;
$('burn2').onclick=()=>{phase='outer';points=outerPath();cursor=0;paused=false;label();$('burn2').hidden=true;$('restart').hidden=false;$('step3').className='complete';$('scene-state').textContent='Higher circular orbit';$('transfer-status').textContent='Burn 2 complete. The spacecraft now circles at '+(vc/Math.sqrt(2)).toFixed(2)+' km/s. Total added velocity: '+(dv1+dv2).toFixed(2)+' km/s.';$('scene-caption').textContent='Two forward burns plus a coast reached the higher circle. Gravity now supplies the inward acceleration at the new radius.';transferDone=true;progress();draw();};
$('restart').onclick=resetTransfer;$('experiment-tab').onclick=()=>setMode('experiment');$('transfer-tab').onclick=$('next').onclick=()=>setMode('transfer');$('delta').oninput=preview;
function adjust(amount){$('delta').value=Math.max(-3,Math.min(3,Number($('delta').value)+amount)).toFixed(1);preview();}
$('subtract').onclick=()=>adjust(-.1);$('add').onclick=()=>adjust(.1);$('zero').onclick=()=>{$('delta').value=0;preview();};$('test').onclick=test;
$('play').onclick=()=>{if(points.length<2)return;paused=!paused;label();};$('replay').onclick=()=>{if(mode==='transfer'){resetTransfer();return;}test();};
$('dv1').textContent=dv1.toFixed(2)+' km/s';$('dv2').textContent=dv2.toFixed(2)+' km/s';
function frame(now){if(!paused&&!document.hidden){cursor=Math.min(points.length-1,cursor+Math.min(now-last,50)*.12);draw();if(cursor>=points.length-1){if(mode==='transfer'&&phase==='coasting')arrive();else{paused=true;label();if(mode==='experiment')$('scene-state').textContent=outcome==='Collision course'?'Surface reached':Math.hypot(points.at(-1).x,points.at(-1).y)>2.35?'Continues beyond view':outcome;}}}last=now;requestAnimationFrame(frame);}preview();requestAnimationFrame(frame);
</script></body></html>
'''
s=s.replace('</style>','''.control-label{display:flex;justify-content:space-between;gap:10px;font-weight:650;margin:18px 0 4px;flex-wrap:wrap}input[type=range]{width:100%;min-height:44px;accent-color:#176b80}input:focus-visible{outline:3px solid #b56d09}.adjustment{flex-wrap:wrap}.adjustment button{flex:1;font-size:12px}.steps{padding-left:24px}.steps li{padding:10px;margin-bottom:8px;border-radius:8px;font-size:14px}.steps .active{background:#fff3d7}.steps .complete{background:#e5f4e9}.transfer-intro{margin-top:16px}.given{font-size:14px}#coast,#restart{margin-top:10px;width:100%}
</style>''')
p.write_text(s,encoding='utf-8')
p=Path('problem-walkthoughs/index.html');s=p.read_text(encoding='utf-8');s=s.replace('<h2>Orbit, Escape, or Crash?</h2>','<h2>Change Speed. Change Orbit.</h2>').replace('Compare three launch speeds, calculate mechanical energy, and explain circular, escaping, and Earth-intersecting paths.','Add or subtract sideways velocity, test the resulting orbit, then perform a two-burn Hohmann transfer.');p.write_text(s,encoding='utf-8')
